import assert from 'node:assert/strict';
import {existsSync,readFileSync,unlinkSync} from 'node:fs';
import {Client,base,requests,server,setActions,tool,until,delay} from './codex-fixture';
const home=base+'/crash-'+Date.now();let c=new Client(home,true,'',false);let pid=0;const marker=home+'/started',finished=home+'/finished';const count=()=>requests.filter(r=>r.generate!==false).length;const alive=(p:number)=>{try{process.kill(p,0);return true}catch{return false}};
try{await c.init();const {thread}=await c.start();const first=await c.turn(thread.id,'saved before crash');await c.done(first.turn.id);setActions(tool('exec_command',{cmd:'echo $$ > '+marker+'; /bin/sleep 30; echo done > '+finished,login:false,yield_time_ms:10000}));await c.turn(thread.id,'crash actual shell');await until(()=>existsSync(marker));pid=Number(readFileSync(marker,'utf8').trim());await c.call('thread/queue/add',{threadId:thread.id,input:[{type:'text',text:'cancelled crash queue marker'}],clientUserMessageId:crypto.randomUUID()});await delay(100);c.proc.kill('SIGKILL');await until(()=>c.proc.signalCode!==null,'owner dead');await delay(100);const survivedOwner=alive(pid);if(survivedOwner){try{process.kill(-pid,'SIGKILL')}catch{process.kill(pid,'SIGKILL')}}await until(()=>!alive(pid),'containment joined');assert.equal(existsSync(finished),false);unlinkSync(marker);const before=count();c=new Client(home,true,'',false);await c.init();const read=await c.call('thread/read',{threadId:thread.id,includeTurns:true});const queue=await c.call('thread/queue/list',{threadId:thread.id});assert.equal(queue.data.length,1);for(const q of queue.data)assert.equal((await c.call('thread/queue/delete',{threadId:thread.id,queuedSubmissionId:q.id})).deleted,true);await c.call('thread/resume',{threadId:thread.id,excludeTurns:true});await delay(300);assert.equal(count(),before);assert.equal(existsSync(marker),false);const fresh=await c.turn(thread.id,'fresh after crash');assert.equal((await c.done(fresh.turn.id)).status,'completed');assert.ok(c.events.some(e=>e.method==='item/completed'&&e.params.turnId===fresh.turn.id&&e.params.item.text==='offline reply'));const payload=requests.filter(r=>r.generate!==false).at(-1);assert.ok(JSON.stringify(payload.input).includes('saved before crash'));assert.equal(existsSync(marker),false);assert.ok(!JSON.stringify(payload.input).includes('cancelled crash queue marker'));console.log(JSON.stringify({case:'Codex-baseline-real-owner-crash',survivedOwner,externalContainmentJoined:true,nativeGoalsDisabled:true,queueRetiredBeforeResume:true,reopenInert:true,noToolReplay:true,historyRestored:true,freshReply:true,priorTurnStatuses:read.thread.turns.map((t:any)=>t.status),toolOutputs:payload.input.filter((i:any)=>i.type==='function_call_output')}));
}finally{await c.close();if(pid&&alive(pid))try{process.kill(-pid,'SIGKILL')}catch{}server.stop(true)}
